 bool refs=true;auto text=[&](uint32_t at){if(!starts.count(at)){refs=false;return std::string{};}return std::string(reinterpret_cast<const char*>(p+offsets[0]+at));};auto row=[&](uint32_t section,uint32_t index){return p+offsets[section]+size_t(index)*strides[section];};
