bool BasementProgressionData::load_file(const char*path,std::string&e){if(!path||!*path)return reject(e,"Basement file path missing");FILE*f=std::fopen(path,"rb");if(!f)return reject(e,"Basement file unavailable");std::vector<uint8_t>b;uint8_t block[4096];bool ok=true;for(;;){const auto n=std::fread(block,1,sizeof block,f);if(b.size()+n>1024*1024){ok=false;break;}b.insert(b.end(),block,block+n);if(n<sizeof block){ok=!std::ferror(f);break;}}if(std::fclose(f))ok=false;if(!ok)return reject(e,"Basement file read rejected");return load(b.data(),b.size(),e);}
bool BasementProgressionData::bind_reviewed_commit(std::string_view pin,std::string&e)const{if(!valid_||pin!=commit_)return reject(e,"Basement reviewed source binding rejected");e.clear();return true;}
const BasementKeyItem*BasementProgressionData::key_item(uint32_t id)const{const auto at=std::find_if(keys_.begin(),keys_.end(),[&](const auto&k){return k.id==id;});return at==keys_.end()?nullptr:&*at;}
const BasementSkill*BasementProgressionData::skill(uint32_t id)const{const auto at=std::find_if(skills_.begin(),skills_.end(),[&](const auto&k){return k.id==id;});return at==skills_.end()?nullptr:&*at;}
BattleValue BasementProgressionData::white_fade(double elapsed)const{if(!valid_||!std::isfinite(elapsed)||elapsed<0)return {};if(elapsed>=fade_length_)return fade_.back().color;const auto right=std::upper_bound(fade_.begin(),fade_.end(),elapsed,[](double t,const auto&k){return t<k.time;});if(right==fade_.begin())return right->color;const auto&left=*(right-1);const auto amount=float((elapsed-left.time)/(right->time-left.time));return {left.color.x+(right->color.x-left.color.x)*amount,left.color.y+(right->color.y-left.color.y)*amount,left.color.z+(right->color.z-left.color.z)*amount,left.color.w+(right->color.w-left.color.w)*amount};}
bool BasementProgressionData::mick_program(bool thoughts,const BasementFlagQuery&query,std::string&program,std::string&e)const{if(!valid_||!query)return reject(e,"Basement NPC selection requires checked flag host");const BasementNpcOverride*selected=nullptr;for(const auto&o:overrides_){if(o.thoughts!=thoughts)continue;bool enabled=o.flag.empty();if(!enabled&&!query(o.flag,enabled,e))return false;if(enabled)selected=&o;}if(!selected||!selected->supported)return reject(e,"Basement selected Mick branch unsupported");program=selected->program;e.clear();return true;}
bool prepare_basement_key_item(const BasementProgressionData&data,uint32_t id,uint32_t uid,const SessionSnapshot&state,SessionSnapshot&out,std::string&e){const auto*policy=data.key_item(id);if(!data.valid()||!policy||!policy->grant)return reject(e,"Basement grant key item unsupported");if(!validate_session_snapshot(state,e))return false;std::set<uint32_t>uids;auto check=[&](const SessionItem&i){if(!uids.insert(i.uid).second)return false;return i.uid!=uid;};for(const auto&c:state.characters)for(const auto&i:c.inventory)if(!check(i))return reject(e,"Basement grant UID collision");for(const auto&i:state.storage)if(!check(i))return reject(e,"Basement grant UID collision");for(const auto&i:state.key_items){const auto known=std::find_if(data.key_items().begin(),data.key_items().end(),[&](const auto&k){return k.source==i.item_id;});if(!check(i)||known==data.key_items().end()||i.equipped||i.doses!=known->doses)return reject(e,"Basement existing key item/UID rejected");}auto next=state;next.key_items.push_back({policy->source,false,policy->doses,uid});if(!validate_session_snapshot(next,e))return false;out=std::move(next);e.clear();return true;}
bool prepare_basement_skill(const BasementProgressionData&data,uint32_t id,const SessionCharacter&state,SessionCharacter&out,std::string&e){const auto*policy=data.skill(id);if(!data.valid()||!policy||policy->character!=state.character_id)return reject(e,"Basement learned skill target rejected");std::set<std::string>seen;for(const auto&s:state.learned_skills)if(!seen.insert(s).second||std::find(data.skill_order().begin(),data.skill_order().end(),s)==data.skill_order().end())return reject(e,"Basement existing learned skill unsupported");auto next=state;if(!seen.count(policy->skill))next.learned_skills.push_back(policy->skill);std::sort(next.learned_skills.begin(),next.learned_skills.end(),[&](const auto&a,const auto&b){return std::find(data.skill_order().begin(),data.skill_order().end(),a)<std::find(data.skill_order().begin(),data.skill_order().end(),b);});out=std::move(next);e.clear();return true;}
bool BasementProgressionConsumer::bind(const BasementProgressionData&data,BasementProgressionHost host,std::string&e){if(!data.valid()||!host.validate_key_item||!host.grant_key_item||!host.validate_skill||!host.learn_skill)return reject(e,"Basement effect host missing");for(const auto&k:data.key_items())if(k.grant&&!host.validate_key_item(k,e))return false;for(const auto&s:data.skills())if(!host.validate_skill(s,e))return false;data_=&data;host_=std::move(host);e.clear();return true;}
bool BasementProgressionConsumer::grant_key_item(uint32_t id,std::string&e){const auto*k=data_?data_->key_item(id):nullptr;if(!k||!k->grant)return reject(e,"Basement unknown grant instruction");return host_.grant_key_item(*k,e);}
bool BasementProgressionConsumer::learn_skill(uint32_t id,std::string&e){const auto*s=data_?data_->skill(id):nullptr;if(!s)return reject(e,"Basement unknown learn instruction");return host_.learn_skill(*s,e);}
